CREATE OR REPLACE FUNCTION public.rsc_check_serial_lifecycle_0092(checked_serial uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    serial public.inventory_serials%ROWTYPE;
    position public.serial_current_positions%ROWTYPE;
    move record;
    original_move public.inventory_movements%ROWTYPE;
    snapshots jsonb := '{}'::jsonb;
    prior jsonb;
    expected_account uuid := NULL;
    expected_owner uuid := NULL;
    expected_movement uuid := NULL;
    expected_cursor bigint := 0;
    expected_status text := 'active';
    terminal_time timestamptz := NULL;
BEGIN
    SELECT * INTO serial FROM public.inventory_serials WHERE id = checked_serial;
    IF NOT FOUND THEN
        RAISE EXCEPTION '0092 serial identity missing' USING ERRCODE = '23514';
    END IF;
    FOR move IN
        SELECT movement.*, tx.ledger_cursor, tx.movement_type, tx.source_document_type, tx.reversed_transaction_id,
               source.owner_org_id AS source_owner, target.owner_org_id AS target_owner, tx.effective_at, source.material_id AS source_material, target.material_id AS target_material,
               source.lot_id AS source_lot, target.lot_id AS target_lot
        FROM public.inventory_movement_serials sn
        JOIN public.inventory_movements movement ON movement.id = sn.movement_id AND movement.transaction_id = sn.transaction_id
        JOIN public.inventory_transactions tx ON tx.id = movement.transaction_id AND tx.status = 'posted'
        LEFT JOIN public.stock_accounts source ON source.id = movement.from_account_id
        LEFT JOIN public.stock_accounts target ON target.id = movement.to_account_id
        WHERE sn.serial_id = checked_serial ORDER BY tx.ledger_cursor, movement.line_no
    LOOP
        IF move.movement_type = 'reversal' AND move.source_document_type = 'work_order_material' THEN
            SELECT * INTO original_move FROM public.inventory_movements WHERE id = expected_movement;
            prior := snapshots->expected_movement::text;
            IF NOT FOUND OR prior IS NULL OR original_move.transaction_id IS DISTINCT FROM move.reversed_transaction_id
               OR move.ledger_cursor <= expected_cursor OR move.from_account_id IS DISTINCT FROM expected_account
               OR move.from_account_id IS DISTINCT FROM original_move.to_account_id
               OR move.to_account_id IS DISTINCT FROM original_move.from_account_id
               OR move.quantity <> original_move.quantity OR move.external_boundary_code IS DISTINCT FROM original_move.external_boundary_code
               OR (move.from_account_id IS NOT NULL AND (move.source_material IS DISTINCT FROM serial.material_id OR move.source_lot IS DISTINCT FROM serial.lot_id))
               OR (move.to_account_id IS NOT NULL AND (move.target_material IS DISTINCT FROM serial.material_id OR move.target_lot IS DISTINCT FROM serial.lot_id))
               OR move.quantity <> (SELECT count(*) FROM public.inventory_movement_serials WHERE movement_id = move.id)
               OR (SELECT count(*) FROM public.material_inventory_policies policy WHERE policy.material_id = serial.material_id
                    AND policy.effective_from <= move.effective_at AND (policy.effective_to IS NULL OR policy.effective_to > move.effective_at)
                    AND policy.tracking_mode IN ('serial','lot_and_serial')) <> 1
               OR NOT EXISTS (SELECT 1 FROM public.work_order_reversal_items item
                    JOIN public.work_order_material_operations original ON original.id = item.original_operation_id
                    JOIN public.work_order_material_operations inverse ON inverse.id = item.inverse_operation_id
                    JOIN public.work_order_reversals parent ON parent.id = item.reversal_id
                    WHERE original.posting_transaction_id = move.reversed_transaction_id AND inverse.posting_transaction_id = move.transaction_id
                      AND inverse.operation_type = 'reverse' AND original.operation_type <> 'reverse'
                      AND original.oam_work_order_id = parent.oam_work_order_id AND inverse.oam_work_order_id = parent.oam_work_order_id)
               OR (prior->>'account')::uuid IS DISTINCT FROM move.to_account_id THEN
                RAISE EXCEPTION '0098 serial inverse requires the last exact original movement' USING ERRCODE = '23514'; END IF;
            IF expected_status IS DISTINCT FROM prior->>'status' THEN terminal_time := move.created_at; END IF;
            expected_status := prior->>'status';
            expected_owner := (prior->>'owner')::uuid;
            expected_account := move.to_account_id;
            expected_movement := move.id;
            expected_cursor := move.ledger_cursor;
            CONTINUE;
        END IF;
        snapshots := snapshots || jsonb_build_object(move.id::text,jsonb_build_object(
            'status',expected_status,'owner',expected_owner::text,'account',expected_account::text));
        IF move.ledger_cursor <= expected_cursor OR move.from_account_id IS DISTINCT FROM expected_account
           OR (expected_status <> 'active' AND NOT (
               expected_status = 'consumed' AND move.movement_type = 'inbound'
               AND move.source_document_type = 'work_order_material' AND move.external_boundary_code IS NOT DISTINCT FROM 'work_order_material_recover'
               AND move.from_account_id IS NULL AND move.to_account_id IS NOT NULL AND move.target_owner IS NOT DISTINCT FROM expected_owner
               AND EXISTS (SELECT 1 FROM public.work_order_replacements replacement
                   JOIN public.work_order_material_operations recovery ON recovery.id = replacement.recover_operation_id
                     AND recovery.replacement_id = replacement.id
                   JOIN public.work_order_replacement_pairs pair ON pair.replacement_id = replacement.id
                     AND pair.operation_id = replacement.consume_operation_id AND pair.removed_serial_id = checked_serial
                   WHERE recovery.posting_transaction_id = move.transaction_id)))
           OR (move.from_account_id IS NULL AND move.to_account_id IS NULL)
           OR (move.from_account_id IS NOT NULL AND (move.source_material IS DISTINCT FROM serial.material_id OR move.source_lot IS DISTINCT FROM serial.lot_id))
           OR (move.to_account_id IS NOT NULL AND (move.target_material IS DISTINCT FROM serial.material_id OR move.target_lot IS DISTINCT FROM serial.lot_id))
           OR move.quantity <> (SELECT count(*) FROM public.inventory_movement_serials WHERE movement_id = move.id)
           OR (SELECT count(*) FROM public.material_inventory_policies policy
               WHERE policy.material_id = serial.material_id AND policy.effective_from <= move.effective_at
                 AND (policy.effective_to IS NULL OR policy.effective_to > move.effective_at)
                 AND policy.tracking_mode IN ('serial', 'lot_and_serial')) <> 1 THEN
            RAISE EXCEPTION '0092 serial ledger chain or dimensions invalid' USING ERRCODE = '23514';
        END IF;
        IF expected_status = 'consumed' THEN
            expected_status := 'active';
            terminal_time := move.created_at;
        END IF;
        IF move.movement_type = 'consume' THEN
            IF move.source_document_type <> 'work_order_material'
               OR move.external_boundary_code IS DISTINCT FROM 'work_order_material_consume'
               OR move.from_account_id IS NULL OR move.to_account_id IS NOT NULL THEN
                RAISE EXCEPTION '0092 serial consumption requires original work order' USING ERRCODE = '23514';
            END IF;
            expected_status := 'consumed';
            terminal_time := move.created_at;
        ELSIF move.movement_type = 'scrap' THEN
            RAISE EXCEPTION '0092 serial scrap requires controlled lifecycle evidence' USING ERRCODE = '23514';
        END IF;
        expected_account := move.to_account_id;
        expected_movement := move.id;
        expected_owner := CASE WHEN move.to_account_id IS NOT NULL THEN move.target_owner ELSE move.source_owner END;
        expected_cursor := move.ledger_cursor;
    END LOOP;
    SELECT * INTO position FROM public.serial_current_positions WHERE serial_id = checked_serial;
    IF serial.lifecycle_status <> expected_status
       OR (terminal_time IS NOT NULL AND serial.updated_at IS DISTINCT FROM terminal_time)
       OR (expected_movement IS NULL AND FOUND)
       OR (expected_movement IS NOT NULL AND (NOT FOUND
           OR position.last_movement_id IS DISTINCT FROM expected_movement
           OR position.stock_account_id IS DISTINCT FROM expected_account)) THEN
        RAISE EXCEPTION '0092 serial lifecycle or position projection drift' USING ERRCODE = '23514';
    END IF;
END;
$function$

